INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('bcdf9c34-1ce1-4944-8c19-f9404cc2214c', 'Ashe', 'ashe/profile_pic.png', 'damage', 2, 'Ashe quickly fires her rifle from the hip or uses her weapon''s aim-down sights to line up a high damage shot at the cost of fire-rate. She blasts enemies by throwing dynamite, and her coach gun packs enough punch to put some distance between her and her foes, or gain some air to leap to hard to reach places or for an aerial shot. And Ashe is not alone, as she can call on her omnic ally B.O.B. to join the fray when the need arises.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('b677b060-b588-4756-b749-411de735c57c', 'Baptiste', 'baptiste/profile_pic.png', 'support', 3, 'Baptiste wields an assortment of experimental devices and weaponry to keep allies alive and eliminate threats under fierce conditions. A battle-hardened combat medic, he is just as capable of saving lives as he is taking out the enemy.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('b3872bd0-8e78-4b38-81a8-c5ae1e833f1d', 'Bastion', 'bastion/profile_pic.png', 'damage', 1, 'The ability to transform between Assault, Recon and devastating Artillery configurations provided Bastion with a high damage output.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('0870c7b8-ca56-4b95-b468-fc0c333c14ce', 'Cassidy', 'cassidy/profile_pic.png', 'damage', 2, 'Armed with his Peacekeeper revolver, Cassidy takes out targets with deadeye precision and dives out of danger with eagle-like speed.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('85766cfe-39fe-42f9-879d-9a5b73855581', 'D-Va', 'd_va/profile_pic.png', 'tank', 2, 'D.Va''s mech is nimble and powerful — its twin Fusion Cannons blast away with autofire at short range, and she can use its Boosters to barrel over enemies and obstacles, or absorb attacks with her projectile-destroying Defense Matrix.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('f338abc3-ec9b-4541-880c-5fe645439abb', 'Doomfist', 'doomfist/profile_pic.png', 'tank', 3, 'Doomfist''s cybernetics make him a highly-mobile, powerful frontline fighter. In addition to dealing ranged damage with his Hand Cannon, Doomfist can slam the ground, knock enemies into the air and off balance, or charge into the fray with his Rocket Punch. When facing a tightly packed group, Doomfist leaps out of view, then crashes down to earth with a spectacular Meteor Strike.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('66eafd7b-f129-4a30-abc4-6a4d2737382d', 'Echo', 'echo/profile_pic.png', 'damage', 2, 'Echo is an evolutionary robot programmed with a rapidly adapting artificial intelligence, versatile enough to fill multiple battlefield combat roles.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('93c893ef-4d4d-442a-8691-e3ac0db849b9', 'Genji', 'genji/profile_pic.png', 'damage', 3, 'Genji flings precise and deadly Shuriken at his targets, and uses his wakizashi to deflect projectiles or delivers a Swift Strike with his technologically-advanced ''dragonblade'' that cuts down enemies.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('7c013ba6-c20e-4c6b-a810-b636390ba3a0', 'Hanzo', 'hanzo/profile_pic.png', 'damage', 3, 'Hanzo''s versatile arrows can reveal his enemies or rapid fire to strike multiple targets. He can scale walls to fire his bow from on high, or summon a titanic spirit dragon.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('a4a169df-23a2-4593-b23e-ce436ffbdced', 'Junker Queen', 'junker_queen/profile_pic.png', 'tank', 3, 'The Junker Queen is designed to take part in close combat with enemy heroes. Many of her abilities apply wounds that cause enemies to slowly drain health. This life-steal passive adds to her survivability and aggression. Pushing the boundaries of brawling, Junker Queen can be considered a ''berserker tank,'' whose survivability is directly connected to how many enemies she''s wounding.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('17322ab2-9183-4098-814d-2ae65ba75a81', 'Junkrat', 'junkrat/profile_pic.png', 'damage', 2, 'Junkrat''s area-denying armaments include a Frag Launcher that lobs bouncing grenades, Concussion Mines that send enemies flying, and Steel Traps that stop foes dead in their tracks.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('5d621cdd-e774-42af-892c-17b019e25130', 'Kiriko', 'kiriko/profile_pic.png', 'support', 2, 'Kiriko is a ninja healer who is aided by her kitsune spirit. She can throw protection suzu to her allies, or kunai against her enemies.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('a6387976-b88c-45b2-97dc-51652a260969', 'Lucio', 'lucio/profile_pic.png', 'support', 2, 'On the battlefield, Lúcio''s cutting-edge Sonic Amplifier buffets enemies with projectiles and knocks foes back with blasts of sound. His songs can both heal his team or boost their movement speed, and he can switch between tracks on the fly.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('18a46b56-da66-4905-8a49-54b8d96d09d3', 'Mei', 'mei/profile_pic.png', 'damage', 3, 'Mei''s weather-altering devices slow opponents and protect locations. Her Endothermic Blaster unleashes damaging icicles and frost streams, and she can Cryo-Freeze herself to guard against counterattacks, or obstruct the opposing team''s movements with an Ice Wall.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('14f14bcf-5d15-4db9-b79d-9fce6d863ec5', 'Mercy', 'mercy/profile_pic.png', 'support', 1, 'Mercy''s Valkyrie Suit helps keep her close to teammates like a guardian angel; healing, resurrecting or strengthening them with the beams emanating from her Caduceus Staff.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('ad15a77a-61b4-4cba-b8de-423e86787593', 'Moira', 'moira/profile_pic.png', 'support', 2, 'Moira''s biotic abilities enable her to contribute healing or damage in any crisis. While Biotic Grasp gives Moira short-range options, her Biotic Orbs contribute longer-range, hands-off damage and healing; she can also Fade to escape groups or remain close to allies in need of support. Once she''s charged Coalescence, Moira can save multiple allies from elimination at once or finish off weakened enemies.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('ded1e3ac-08ea-4e86-be9a-ab49b7a39a38', 'Orisa', 'orisa/profile_pic.png', 'tank', 2, 'In Overwatch, Orisa served as the central anchor of her team, and defended her teammates from the frontline with a protective barrier. She could attack from long range, fortify her own defenses, launch graviton charges to slow and move enemies, and deploy a Supercharger to boost the damage output of multiple allies at once.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('56cd59d5-b3a9-4958-a9e1-1bb9a8464a2a', 'Pharah', 'pharah/profile_pic.png', 'damage', 1, 'Soaring through the air in her combat armor, and armed with a launcher that lays down high-explosive rockets, Pharah is a force to be reckoned with.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('0bf6b821-78ed-42f2-bede-67574f46c7c8', 'Reaper', 'reaper/profile_pic.png', 'damage', 1, 'Hellfire Shotguns, the ghostly ability to become immune to damage, and the power to step between shadows make Reaper one of the deadliest beings on Earth.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('eff5b31c-560a-44b2-b728-f38b920b995b', 'Reinhardt', 'reinhardt/profile_pic.png', 'tank', 1, 'Clad in powered armor and swinging his hammer, Reinhardt leads a rocket-propelled charge across the battleground and defends his squadmates with a massive energy barrier.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('12f96cb5-50a0-4e3a-88c3-0468cf87f7e4', 'Roadhog', 'roadhog/profile_pic.png', 'tank', 1, 'Roadhog uses his signature Chain Hook to pull his enemies close before shredding them with blasts from his Scrap Gun. He''s hardy enough to withstand tremendous damage, and can recover his health with a short breather.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('5428a23b-453c-4d58-a881-32754dd53b28', 'Soldier: 76', 'soldier__76/profile_pic.png', 'damage', 1, 'Armed with cutting-edge weaponry, including an experimental pulse rifle that''s capable of firing spirals of high-powered Helix Rockets, Soldier: 76 has the speed and support know-how of a highly trained warrior.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('c6690334-3934-48d7-926f-13e7a8183c5d', 'Sombra', 'sombra/profile_pic.png', 'support', 3, 'Stealth and debilitating attacks make Sombra a powerful infiltrator. Her hacking can disrupt her enemies, ensuring they''re easier to take out, while her EMP provides the upper hand against multiple foes at once. Sombra''s ability to Translocate and camouflage herself makes her a hard target to pin down.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('742d8fc2-0cea-4ee1-9535-0f2f6b3f98f7', 'Symmetra', 'symmetra/profile_pic.png', 'support', 2, 'Symmetra utilizes her light-bending Photon Projector to dispatch adversaries, shield her associates, construct teleportation pads and deploy particle-blasting Sentry Turrets.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('0268b323-3921-46f9-9b9b-4da7603354a1', 'Torbjörn', 'torbj_rn/profile_pic.png', 'damage', 2, 'Torbjörn''s extensive arsenal includes a rivet gun and hammer, as well as a personal forge that he can use to build turrets.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('c5ec96b9-4f6b-4fca-ba6a-8f5aa92da3b9', 'Tracer', 'tracer/profile_pic.png', 'damage', 2, 'Toting twin pulse pistols, energy-based time bombs, and rapid-fire banter, Tracer is able to ''blink'' through space and rewind her personal timeline as she battles to right wrongs the world over.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('a228388f-d0d0-4a61-aa1b-6e39d1892f10', 'Widowmaker', 'widowmaker/profile_pic.png', 'damage', 2, 'Widowmaker equips herself with whatever it takes to eliminate her targets, including mines that dispense poisonous gas, a visor that grants her squad infra-sight, and a powerful sniper rifle that can fire in fully-automatic mode.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('9b368987-4926-433e-875c-b7b326077b6a', 'Winston', 'winston/profile_pic.png', 'tank', 2, 'Winston wields impressive inventions—a jump pack, electricity-blasting Tesla Cannon, portable shield projector and more—with literal gorilla strength.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('17d09af9-f33d-45f7-979a-b13d72e31f7c', 'Wrecking Ball', 'wrecking_ball/profile_pic.png', 'tank', 3, 'Wrecking Ball rolls across the battlefield, using his arsenal of weapons and his mech''s powerful body to crush his enemies.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('22a73e6a-0903-4c63-80e4-52be25cfe5ee', 'Zarya', 'zarya/profile_pic.png', 'tank', 3, 'Deploying powerful personal barriers that convert incoming damage into energy for her massive Particle Cannon, Zarya is an invaluable asset on the front lines of any battle.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('a64b7529-c947-478f-8cb9-12653a9a896b', 'Zenyatta', 'zenyatta/profile_pic.png', 'support', 3, 'Zenyatta calls upon orbs of harmony and discord to heal his teammates and weaken his opponents, all while pursuing a transcendent state of immunity to damage.');
INSERT INTO overwatch.hero (hero_uuid, name, hero_image, type, difficulty, description) VALUES ('7e632fbb-347e-43ac-8d38-83eecb67d297', 'Ana', 'ana/profile_pic.png', 'support', 3, 'Ana''s versatile arsenal allows her to affect heroes all over the battlefield. Her Biotic Rifle rounds and Biotic Grenades heal allies and damage or impair enemies; her sidearm tranquilizes key targets, and Nano Boost gives one of her comrades a considerable increase in power.');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('9b64a145-c8ac-405b-a4cc-93aa7469d2ea', 'Sleep Dart', 'Ability', 'ana/sleep_dart.png', '7e632fbb-347e-43ac-8d38-83eecb67d297');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('aac29399-6292-4cf7-8abf-07843f0dbd42', 'Biotic Grenade', 'Ability', 'ana/biotic_grenade.png', '7e632fbb-347e-43ac-8d38-83eecb67d297');
