INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('9cfd16e9-8afe-4cf7-8e6e-c034941f4e8c', 'Magnetic Grenade', 'Ability', 'cassidy/magnetic_grenade.png', '0870c7b8-ca56-4b95-b468-fc0c333c14ce');
