INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('4e9c4983-c149-48d2-a33f-81d049d0cd7f', 'Rocket Punch', 'Secondary Weapon', 'doomfist/rocket_punch.png', 'f338abc3-ec9b-4541-880c-5fe645439abb');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('b5fe0480-d16b-4f67-9c36-e302c86dc5b5', 'Seismic Slam', 'Ability', 'doomfist/seismic_slam.png', 'f338abc3-ec9b-4541-880c-5fe645439abb');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('6b6bfda7-e306-4d7e-bdf3-e46e702153ef', 'Power Block', 'Ability', 'doomfist/power_block.png', 'f338abc3-ec9b-4541-880c-5fe645439abb');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('ab680717-58a8-4958-bbb9-1d4797814c40', 'Meteor Strike', 'Ultimate', 'doomfist/meteor_strike.png', 'f338abc3-ec9b-4541-880c-5fe645439abb');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('9dffacd1-30f7-4099-8cdd-86c4cfa6ee34', 'The Best Defense...', 'Passive', 'doomfist/the_best_defense___.png', 'f338abc3-ec9b-4541-880c-5fe645439abb');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('e9868632-3f59-4a0e-b442-2930ef40ffe4', 'Tri-Shot', 'Primary Weapon', 'echo/tri_shot.png', '66eafd7b-f129-4a30-abc4-6a4d2737382d');
INSERT INTO overwatch.ability (ability_uuid, name, type, ability_image, fk_hero_uuid) VALUES ('92eea225-6db5-48f4-a4f6-9fcbd39d0731', 'Sticky Bombs', 'Secondary Weapon', 'echo/sticky_bombs.png', '66eafd7b-f129-4a30-abc4-6a4d2737382d');
