INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('0735532c-672d-4f32-85be-5d47e4232689', 'Hybrid', 'Hybrid maps are a mixture of Assault and Escort maps. There is an Objective A for attackers to capture, and after it is captured, attackers must escort a payload across two checkpoints.', 2);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('6c9380ef-169d-44b2-abca-2580c3348227', 'Control', 'Control maps are unique because they are essentially three different smaller maps that all co-exist in one larger area.', 3);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('cdcd8895-1c87-4c2c-b379-84425681297c', 'Push', 'Push maps are the newest additions to Overwatch, released with Overwatch 2. They are symmetrical with a robot at the center of the map. Each team has a block that the robot has to push to their respective ends, but only 1 team can control the robot at a time and the opposing team has to take control of the robot to push their own block.', 4);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('2ebf5d09-9b3e-406b-b173-941ff307ede8', 'Assault', 'Assault maps have two rectangular areas that the attackers must capture: Objective A and Objective B. Objective A is between the attacker and defender spawn rooms, and Objective B is in front of the defender spawn room.', 5);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('b09e3609-d8cb-419c-b0fa-ca4bd632a1f0', 'Elimination', 'Elimination maps, or Arena maps, are small, symmetrical maps with a spawn room at each end. They are designed for intense straightforward combat. They are also used for 1v1 Duels.', 6);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('fe8fe943-ac49-4658-9684-f01c90fa4b35', 'Deathmatch', 'Deathmatch maps are unique because they have no spawn room. They are designed to accommodate as many fighting styles as possible. ', 7);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('dbecfac5-c27d-4e6e-918d-bb3a3378fd66', 'Capture the Flag', 'Capture the Flag maps are large, symmetrical maps with a spawn room at each end. Near each spawn room is the flag area with a flag that the other team must steal and bring to their own area.', 8);
INSERT INTO overwatch.map_mode (map_mode_uuid, type, description, index) VALUES ('7ab36a54-6b93-4de8-87e1-48ed957747db', 'Escort', 'Escort maps have a payload that the attackers must escort across three checkpoints.', 1);
